import{z as o,x as s,o as e,c as d,q as n,j as r,D as B,d as A,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"事件驱动全景","description":"","frontmatter":{"title":"事件驱动全景","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/event-driven-overview.md","filePath":"quant/event-driven-overview.md","lastUpdated":1791413859000}'),p={name:"quant/event-driven-overview.md"};function C(u,E,D,h,m,F){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="事件驱动全景" tabindex="-1">事件驱动全景 <a class="header-anchor" href="#事件驱动全景" aria-label="Permalink to &quot;事件驱动全景&quot;">​</a></h1><div class="epigraph"><p>事件驱动吃的是公告后的不完备定价与交易摩擦，不是截面因子的慢溢价；每类事件有自己的失败模式。</p><footer>—— 并购套利见 Mitchell and Pulvino；对照事件研究法的识别，本课只做策略地图</footer></div><p><a href="/quant/one-thirty-thirty">上一课</a>把 130/30 写成带有限卖空的增强指数：净暴露约 100%，不是市场中性，评价用 TE 与超额。缺口是日历：多空与 130/30 仍是截面组合，并购、分拆、重组、破产的完成时点由公司事件驱动，不能收成同一个「事件因子」。本课给事件驱动地图：公告、完成不确定性、资金占用，按完成风险对漂移风险分桶。不重讲 30% 借券。具体一类见 <a href="/quant/event-study">事件研究</a> 与 <a href="/quant/merger-arbitrage">并购套利</a>；后课全球宏观默认事件簿的平静期夏普不能当容量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>130/30 仍按截面日历再平衡；并购与破产的完成日不是月末。<a href="/quant/pead-sue">PEAD</a> 是盈余公告后的漂移，偏系统、可做截面。并购套利是 deal 完成的二元风险，偏特异、相关在监管否决时会突然升。分拆、毒丸、指数事件（后课纳入）又不同。问题是资金与风险预算：事件簿的「夏普」在平静期高，在 2008 年并购破裂期一起爆。地图要按<strong>完成风险 vs 漂移风险</strong>分桶，而不是按彭博行业标签。</p><p><span class="marginnote">并购价差的数字例子：收购方报价 50 元，目标现价 47 元，价差 3 元约 6.4%；若交易预计 4 个月完成，年化约 19%。这 19% 不是无风险收益，是对「交易破裂」的定价——一旦破裂，目标股价通常跌回收购前水平之下，单笔亏损可吞掉许多笔积累的价差。</span></p><p>共同零件：公告日流动性空洞、借券、法律文件、完成日不确定。回测若用公告后收盘价当成交，会高估，见 <a href="/quant/event-study">事件研究</a> 的时间戳。</p><h3 id="不要用因子模型解释掉事件" tabindex="-1">不要用因子模型解释掉事件 <a class="header-anchor" href="#不要用因子模型解释掉事件" aria-label="Permalink to &quot;不要用因子模型解释掉事件&quot;">​</a></h3><p>事件收益对 HML/动量有暴露，但残差才是策略。强行行业中性可能对冲掉并购价差本身。风险模型应用于剩余，并对单笔 deal 设集中限额。</p><p><span class="marginnote">SPAC、PIPEs、困境债各有法律与流动性结构，不能从现金并购公式类推。地图只点名，细节留给专门产品课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分类：并购套利、分拆/配售、困境/破产、盈余漂移、监管/政策事件。每类写：催化剂、失败模式、对冲（行业、指数、期权）、容量。组合：低相关的事件之间分散，但承认体制相关（信贷紧缩）。执行：公告后冲击模型单独校准。</p>',12)),(e(),r(l,null,{default:B(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22%E4%BA%8B%E4%BB%B6%E7%B0%BF%E6%8C%89%E5%AE%8C%E6%88%90%E9%A3%8E%E9%99%A9%E5%88%86%E6%A1%B6%22%5D%20--%3E%20A%5B%22%E5%B9%B6%E8%B4%AD%E5%A5%97%E5%88%A9%EF%BC%9A%E5%82%AC%E5%8C%96%E5%89%82%E6%98%AF%E4%BA%A4%E6%98%93%E5%AE%8C%E6%88%90%22%5D%0A%20%20MAP%20--%3E%20B%5B%22%E5%9B%B0%E5%A2%83%E4%B8%8E%E7%A0%B4%E4%BA%A7%EF%BC%9A%E6%B8%85%E7%AE%97%E4%B8%8E%E9%87%8D%E7%BB%84%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20MAP%20--%3E%20C%5B%22%E5%88%86%E6%8B%86%E4%B8%8E%E9%85%8D%E5%94%AE%EF%BC%9A%E6%8C%87%E6%95%B0%E4%B8%8E%E8%A2%AB%E5%8A%A8%E4%B9%B0%E7%9B%98%22%5D%0A%20%20MAP%20--%3E%20D%5B%22%E7%9B%88%E4%BD%99%E6%BC%82%E7%A7%BB%20PEAD%EF%BC%9A%E5%85%AC%E5%91%8A%E5%90%8E%E6%BC%82%E7%A7%BB%22%5D%0A%20%20MAP%20--%3E%20E%5B%22%E7%9B%91%E7%AE%A1%E4%B8%8E%E6%94%BF%E7%AD%96%E4%BA%8B%E4%BB%B6%EF%BC%9A%E5%AE%A1%E6%89%B9%E6%97%B6%E9%92%9F%22%5D%0A%20%20A%20--%3E%20F%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%EF%BC%9A%E4%BA%A4%E6%98%93%E7%A0%B4%E8%A3%82%EF%BC%8C%E7%9B%B8%E5%85%B3%E6%80%A7%E9%AA%A4%E5%8D%87%22%5D%0A%20%20B%20--%3E%20G%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%EF%BC%9A%E6%B5%81%E5%8A%A8%E6%80%A7%E8%92%B8%E5%8F%91%E4%B8%8E%E5%81%9C%E7%89%8C%22%5D%0A%20%20C%20--%3E%20H%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%EF%BC%9A%E5%AF%B9%E5%88%86%E6%8B%86%E4%BB%B7%E5%80%BC%E7%9A%84%E8%AF%AF%E5%88%A4%22%5D%0A%20%20D%20--%3E%20I%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%EF%BC%9A%E6%BC%82%E7%A7%BB%E8%A1%B0%E5%87%8F%E6%88%96%E6%B6%88%E5%A4%B1%22%5D%0A%20%20E%20--%3E%20J%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%EF%BC%9A%E6%97%B6%E9%92%9F%E5%BB%B6%E9%95%BF%E5%8D%A0%E7%94%A8%E8%B5%84%E9%87%91%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"事件把信息集中释放，市场在完成概率上交易。策略卖的是「概率被标错」或「有人要流动性」。因子策略卖的是长期风险补偿。时钟不同，拥挤模式也不同：并购套利的拥挤是 spread 过窄，因子拥挤是估值压缩。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"平静期与破裂期可以类比晴天与台风天：平时各条航线独立延误，组合波动很小；台风一来所有航班一起停飞，相关性逼近 1。Mitchell and Pulvino 的发现正是并购套利在市场大跌、交易密集破裂时与市场同步下跌——用平静期夏普定容量与杠杆，等于按晴天订机队。")],-1)),(e(),r(l,null,{default:B(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Ann%5B%22%E5%85%AC%E5%91%8A%22%5D%20--%3E%20Drift%5B%22%E6%BC%82%E7%A7%BB%E7%B1%BB%20PEAD%22%5D%0A%20%20Ann%20--%3E%20Bin%5B%22%E5%AE%8C%E6%88%90%E7%B1%BB%20%E5%B9%B6%E8%B4%AD%22%5D%0A%20%20Drift%20--%3E%20Sys%5B%22%E5%8F%AF%E6%88%AA%E9%9D%A2%E5%8C%96%22%5D%0A%20%20Bin%20--%3E%20Idio%5B%22Deal%20%E9%A3%8E%E9%99%A9%E5%8A%A0%E4%BD%93%E5%88%B6%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>内幕与重大非公开信息是法律边界，本课只处理公开公告后的交易。跨境并购的监管时钟更长。不要把未公告谣言当事件驱动回测。</p><p><span class="marginnote">常见误区：把并购套利当「类固定收益」。它的日度波动确实小，但收益结构是卖出尾部保险：多数月份收小额价差，少数月份一次破裂亏掉多年积累。评价要看最差月份与破裂情景回测，而不是月度胜率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件驱动按完成风险与漂移风险分桶，不是一个因子。</li><li>平静期夏普不可外推到破裂期的相关 1。</li><li>时间戳与冲击决定回测是否可交易。</li><li>出处：Mitchell and Pulvino, <em>Journal of Finance</em>, 2001（并购套利）；盈余漂移见 PEAD 课文献。</li></ul>',5))])}const v=o(p,[["render",C]]);export{P as __pageData,v as default};
